    fn build_query(&self) -> Result<String> {
        let mut query_params = Vec::new();

        if let Some(archived) = self.internal.archived {
            query_params.push(("archived".to_owned(), archived.to_string()));
        }

        if let Some(ref visibility) = self.internal.visibility {
            query_params.push(("visibility".to_owned(), visibility.to_string()));
        }

        if let Some(ref order_by) = self.internal.order_by {
            query_params.push(("order_by".to_owned(), order_by.to_string()));
        }

        if let Some(ref sort) = self.internal.sort {
            query_params.push(("sort".to_owned(), sort.to_string()));

