            // If the request is for a static file, and it exists, serve it.
            if self.dist.try_handle(&mut proxy).is_ok() {
                return Ok(proxy.finish());
            }

            // Otherwise, let the next handler in the chain handle it.
            handler.handle(request)
        } else {
            // This should ideally never happen if `with_handler` is called.
            Err("Middleware was not initialized with a handler".into())
        }
    }
