/// encrypt data with ChaCha20 and then authenticate it with HMAC-SHA512
    pub fn encrypt_and_auth(&self, message: &[u8]) -> Vec<u8> {
        let mut ciphertext = chacha20::encrypt(message, &self.nonce, &self.encryption_key);
        let auth_tag = hmacsha512256::authenticate(&ciphertext, &self.authentication_key);
        let hmacsha512256::Tag(auth_slice) = auth_tag;

        ciphertext.extend_from_slice(auth_slice);
        ciphertext
    }

    /// decrypt data that has been encrypted and authenticated with ChaCha20-HMAC-SHA512
